118	        let mut config = Config::default();
119	        config.sources.insert(key, PathBuf::from(path));
120	        config
121	    }
122	
123	    #[test]
124	    fn the_flag_wins_then_the_file_then_the_default() {
125	        let config = config_with_source("blocks", "iiac-perf.md");
126	        assert_eq!(
