157	/// Decide what to do with the config at `path`, whose current text is `existing` (`None` when
158	/// no file exists), given the live `[freq]` section lines. Pure, so the decision is tested
159	/// without a filesystem.
160	fn plan_config(
161	    path: &Path,
162	    existing: Option<&str>,
163	    section: &[String],
164	) -> Result<ConfigPlan, String> {
165	    let md = path.extension().is_some_and(|e| e == "md");
166	    let Some(text) = existing else {
167	        let body = if md {
168	            format!("# iiac-perf config\n\n{}", md_section(section))
169	        } else {
170	            toml_section(section)
171	        };
172	        return Ok(ConfigPlan::Create {
173	            path: path.to_path_buf(),
174	            text: body,
175	        });
176	    };
177	    let parsed = config::parse_text(path, text)?;
178	    if parsed.freq.is_some() {
