180	            path: path.to_path_buf(),
181	            config: parsed,
182	        });
183	    }
184	    let separator = if text.is_empty() || text.ends_with("\n\n") {
185	        ""
186	    } else if text.ends_with('\n') {
187	        "\n"
188	    } else {
189	        "\n\n"
190	    };
191	    let addition = if md {
192	        md_section(section)
193	    } else {
194	        toml_section(section)
195	    };
196	    let addition = format!("{separator}{addition}");
197	    Ok(ConfigPlan::Append {
198	        path: path.to_path_buf(),
199	        whole: format!("{text}{addition}"),
200	        text: addition,
201	    })
202	}
