attachment.snippet:
1	//! The `setup` command word: make a host ready for iiac-perf.
2	//!
3	//! A host was ready only after hand work, its `[freq]` steady state written into the XDG config
4	//! with the clamp limits a restore needs, and the limits are what a hand forgets (the 7600x's
5	//! declaration omitted them, and a restore there fell to 427 MHz). `setup` writes the declaration
6	//! from the live state instead.
7	//!
8	//! - **Print by default, write with `--apply`**: the plain command shows exactly what `--apply`
9	//!   would write and where, so the file is reviewed before it exists.
10	//! - **Never overwrite**: a missing file is created, a file without `[freq]` gains one at its
11	//!   end, and a file that already declares `[freq]` is left alone and checked, since it may hold
12	//!   profiles and knobs nobody wants regenerated.
13	//! - **Checked before written**: the new text must parse and pass the same steady-state checks
14	//!   every pin and restore applies, so a pinned clamp at setup time refuses rather than writing a
15	//!   pin as the steady state.
16	//! - **An existing declaration is checked against the live state too**: one can fit the hardware
17	//!   range and still be another host's, as the 7600x's once was, so `setup` names every declared
18	//!   value the host does not run at.
19	//! - **Run as the user**: the config belongs under the user's home, and under sudo `$HOME` may
20	//!   be root's.
21	//! - **Permissions by ownership, once**: a udev rule hands the user the cpufreq files a pin or
22	//!   restore writes and `/dev/cpu_dma_latency`, so those commands run without sudo. `--apply`
23	//!   calls sudo once to install the rule and take ownership now, and `--uninstall --apply` removes
24	//!   the rule and gives the files back to root. Ownership rather than a POSIX ACL, since we think
25	//!   sysfs does not reliably support ACLs, while chown on its files is what udev rules already do.
26	
27	use std::io::Write;
28	use std::os::unix::fs::MetadataExt;
29	use std::path::{Path, PathBuf};
30	
31	use crate::config;
32	use crate::freqctl;
33	
34	/// What `setup` does with the XDG config file.
35	#[derive(Debug, PartialEq)]
36	enum ConfigPlan {
37	    /// No file exists: create it with this text.
38	    Create { path: PathBuf, text: String },
39	    /// The file exists without `[freq]`: append this text to it, `whole` being the file after.
40	    Append {
41	        path: PathBuf,
42	        text: String,
43	        whole: String,
44	    },
45	    /// The file already declares `[freq]`: leave it, and check what it declares.
46	    Declared {
47	        path: PathBuf,
48	        config: Box<config::Config>,
49	    },
50	}
51	
52	/// Where the permissions rule lives.
53	const RULE_PATH: &str = "/etc/udev/rules.d/70-iiac-perf.rules";
54	
55	/// The wake-latency clamp device the permissions also hand over, for the pin-idle knob.
56	const DMA_LATENCY: &str = "/dev/cpu_dma_latency";
57	
58	/// The `setup` command: print the plan, and carry it out with `apply`. `uninstall` plans the
59	/// permissions' removal instead and leaves the config alone. Exit 0 when the host is ready (or
60	/// would be, printing), 1 when a step failed or a declaration does not pass, 2 on a refusal to
61	/// run.
62	pub fn run(apply: bool, uninstall: bool) -> i32 {
63	    if is_root() {
64	        eprintln!(
65	            "error: setup: run it as your user, not under sudo: the config belongs under your \
66	             home, $HOME under sudo may be root's, and setup calls sudo itself for the \
67	             permissions"
68	        );
69	        return 2;
70	    }
71	    let user = match std::env::var("USER") {
72	        Ok(u) if plain_account_name(&u) => u,
73	        Ok(u) => {
74	            eprintln!(
75	                "error: setup: USER {u:?} is not a plain account name: it is written into a udev \
76	                 rule and a root script"
77	            );
78	            return 2;
79	        }
80	        Err(_) => {
81	            eprintln!("error: setup: USER is unset: cannot name whose the permissions are");
82	            return 2;
83	        }
84	    };
85	    let ok = if uninstall {
86	        permissions_step(apply, &user, true)
87	    } else {
88	        // Both steps run even when the first fails, so one invocation reports everything.
89	        let config_ok = config_step(apply);
90	        println!();
91	        let permissions_ok = permissions_step(apply, &user, false);
92	        config_ok && permissions_ok
93	    };
94	    if ok { 0 } else { 1 }
95	}
96	
97	/// Whether `name` is safe to write unquoted into a udev rule and a shell script: letters, digits,
98	/// `_`, `.`, and `-`, not leading with `-`.
99	fn plain_account_name(name: &str) -> bool {
100	    !name.is_empty()
101	        && !name.starts_with('-')
102	        && name
103	            .bytes()
104	            .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'_' | b'.' | b'-'))
105	}
106	
107	/// Whether the process runs as root.
108	fn is_root() -> bool {
109	    // SAFETY: geteuid takes no arguments, cannot fail, and touches no memory.
110	    unsafe { libc::geteuid() == 0 }
111	}
112	
113	/// The config step: plan, check, print, and with `apply` write. Returns whether the host's
114	/// declaration is (or, printing, would be) one every pin and restore accepts.
115	fn config_step(apply: bool) -> bool {
116	    let path = match config::xdg_target() {
117	        Ok(Some(p)) => p,
118	        Ok(None) => {
119	            eprintln!("error: setup: neither XDG_CONFIG_HOME nor HOME is set: no config home");
120	            return false;
121	        }
122	        Err(e) => {
123	            eprintln!("error: setup: {e}");
124	            return false;
125	        }
126	    };
127	    let section = match freqctl::freq_section() {
128	        Ok(lines) => lines,
129	        Err(e) => {
130	            eprintln!("error: setup: {e}");
131	            return false;
132	        }
133	    };
134	    let existing = match std::fs::read_to_string(&path) {
135	        Ok(text) => Some(text),
136	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => None,
137	        Err(e) => {
138	            eprintln!("error: setup: reading {}: {e}", path.display());
139	            return false;
