            eprintln!("error: restore-freq: {e}");
            return 2;
        }
    };
    if let Err(e) = apply(&plan) {
        eprintln!("error: restore-freq: {e}");
        return 1;
    }
    println!("restored the declared [freq] steady state");
    for line in state_lines() {
        println!("{line}");
    }
    0
}

