128	        let mut config = Config::default();
129	        config.sources.insert(key, PathBuf::from(path));
130	        config
131	    }
132	
133	    #[test]
134	    fn the_flag_wins_then_the_file_then_the_default() {
135	        let config = config_with_source("blocks", "iiac-perf.md");
136	        assert_eq!(
137	            layered(Some(10), "--blocks", Some(50), "blocks", &config, 100),
138	            (10, Source::Flag("--blocks".to_string()))
