151	                100
152	            ),
153	            (100, Source::Default)
154	        );
155	    }
156	
157	    #[test]
158	    fn a_source_restating_the_default_is_marked() {
159	        let file = Source::File(PathBuf::from("iiac-perf.md"));
160	        let same = Param::new("blocks", "100".to_string(), "100", file.clone());
161	        assert_eq!(source_cell(&same), "(iiac-perf.md, same as default)");
162	        let differs = Param::new("blocks", "50".to_string(), "100", file);
163	        assert_eq!(source_cell(&differs), "(iiac-perf.md)");
