120	            return false;
121	        }
122	        Err(e) => {
123	            eprintln!("error: setup: {e}");
124	            return false;
125	        }
126	    };
127	    let section = match freqctl::freq_section() {
128	        Ok(lines) => lines,
129	        Err(e) => {
130	            eprintln!("error: setup: {e}");
131	            return false;
132	        }
133	    };
134	    let existing = match std::fs::read_to_string(&path) {
