139	            return false;
140	        }
141	    };
142	    let plan = match plan_config(&path, existing.as_deref(), &section) {
143	        Ok(p) => p,
144	        Err(e) => {
145	            eprintln!("error: setup: {e}");
146	            return false;
147	        }
148	    };
149	    match plan {
150	        ConfigPlan::Declared { path, config } => {
